+      lead: getPartnerLeadById(intent.leadId, { viewerPartnerId: intent.partnerId }),
+      fromStatus: existingLead.status,
+    };
+  });
+
+  return tx({ intentId, action, verifiedBy, adminNote, verifiedAt });
