import path from "path";
import request from "supertest";

process.env.NODE_ENV = "test";
process.env.SQLITE_PATH = "data/gadgetpe-intent-e2e.sqlite";
process.env.JWT_ACCESS_SECRET = "test-access-secret";
process.env.JWT_REFRESH_SECRET = "test-refresh-secret";
process.env.ADMIN_DEV_KEY = "admin-dev-key";

const db = path.resolve(process.cwd(), process.env.SQLITE_PATH);
for (const file of [db, `${db}.lock`, `${db}-shm`, `${db}-wal`]) {
  if (fs.existsSync(file)) fs.rmSync(file, { force: true, recursive: true });
}

const { app } = await import("../src/app.js");

function ok(name, condition) {
  if (!condition) throw new Error(`SMOKE failed: ${name}`);
  console.log(`ok - ${name}`);
}

async function createPartner(phone) {
  await request(app).post("/api/v1/auth/partner/otp/send").send({ phone }).expect(200);
  const result = await request(app)
    .post("/api/v1/auth/partner/otp/verify")
    .send({ phone, otp: "6767", name: "Smoke Partner" })
    .expect(200);
  return result.body.data;
}

async function createUser(phone) {
  await request(app).post("/api/v1/auth/user/otp/send").send({ phone }).expect(200);
  const result = await request(app)
    .post("/api/v1/auth/user/otp/verify")
    .send({ phone, otp: "6767", name: "Smoke User" })
    .expect(200);
  return result.body.data;
}

const partner = await createPartner("9000099901");
const user = await createUser("8000099901");
